// waybar (GTK CSS): все роли как @define-color uiu_<role>. style.css в dotfiles
// импортирует файл и ссылается только на @uiu_* — никаких hex в style.css.

import type { Theme } from "../theme";

export const gtkName = (role: string) => `uiu_${role.replace(/^--/, "").replaceAll("-", "_")}`;

export function waybar(t: Theme): string {
  const lines = [
    "/* uiu — waybar colors (light)",
    "   generated by packages/theme-gen from theme/*.css — do not edit by hand */",
    "",
  ];
  for (const name of t.roles.keys()) {
    const role = name.slice(2);
    lines.push(`@define-color ${gtkName(role)} ${t.role(role).hex};`);
  }
  lines.push("");
  return lines.join("\n");
}
